import { type TsDsl, TypeScriptRenderer } from "@hey-api/openapi-ts";

type RenderArgs = Parameters<typeof TypeScriptRenderer.astToString>[0];

/** One import declaration, in the shape Hey API's renderer prints. */
export type ModuleImport = NonNullable<RenderArgs["imports"]>[number][number];

export const GENERATED_HEADER =
  "// AUTO-GENERATED by ir-kit/sdk/k6 — do not edit by hand.";

export interface PrintModuleInput {
  /** Leading comment block. */
  header?: string;
  /** Import declarations, printed in order. */
  imports?: ReadonlyArray<ModuleImport>;
  /** Top-level statements. */
  nodes: ReadonlyArray<TsDsl>;
  /** Code printed after the nodes, for things the DSL can't build (e.g. `export default`). */
  footer?: string;
}

/** Render a module from DSL nodes. */
export function printModule(input: PrintModuleInput): string {
  const body = TypeScriptRenderer.astToString({
    imports: input.imports?.length ? [input.imports] : undefined,
    nodes: input.nodes,
  }).trim();
  return `${[input.header, body, input.footer].filter(Boolean).join("\n\n")}\n`;
}

/** Render DSL nodes into a source-file string. */
export function printDslNodes(
  nodes: ReadonlyArray<TsDsl>,
  header?: string,
): string {
  return printModule({ header, nodes });
}
